data.script:
const bookmark=Bookmark.findOrCreate('Functional QA Folder');
if(!bookmark)throw Error('No QA bookmark selected');
const fm=FileManager.createForBookmark(bookmark);
const expected='Neutral bookmark source — café 🐼\n';
if(fm.readString('source.txt')!==expected)throw Error('Unexpected neutral source: '+fm.lastError);
if(fm.readString('missing.txt')!==undefined||!fm.lastError)throw Error('Missing-file error was not reported');
const result='Bookmark action read/write passed — café 🐼\n';
if(!fm.writeString('result.txt',result))throw Error('Write failed: '+fm.lastError);
if(fm.readString('result.txt')!==result)throw Error('Readback failed: '+fm.lastError);
context.addSuccessParameter('bookmarkResult','passed');
app.displayInfoMessage('Bookmark action read/write passed');
